PROGRAM elevator
VAR_INPUT
    CallUp : BOOL;
    CallDown : BOOL;
    DoorClosed : BOOL;
    AtTop : BOOL;
    AtBottom : BOOL;
END_VAR
VAR_OUTPUT
    MotorUp : BOOL;
    MotorDown : BOOL;
END_VAR
VAR
    State : INT;
END_VAR

CASE State OF
    0: // At-bottom
        IF CallUp AND DoorClosed THEN
            State := 1;
        ELSIF NOT AtBottom THEN
            State := 2;
        END_IF;

    1: // Moving-up
        IF CallDown AND DoorClosed THEN
            State := 3;
        ELSIF AtTop OR NOT DoorClosed THEN
            State := 2;
        END_IF;

    2: // At-top
        IF CallDown AND DoorClosed THEN
            State := 3;
        ELSIF NOT AtTop THEN
            State := 0;
        END_IF;

    3: // Moving-down
        IF CallUp AND DoorClosed THEN
            State := 1;
        ELSIF AtBottom OR NOT DoorClosed THEN
            State := 0;
        END_IF;
END_CASE;

CASE State OF
    0, 2: MotorUp := FALSE; MotorDown := FALSE;
    1: MotorUp := TRUE; MotorDown := FALSE;
    3: MotorUp := FALSE; MotorDown := TRUE;
END_CASE;

END_PROGRAM

PROGRAM elevator
