PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME literal := T#3s;
END_VAR

IF NOT EStop THEN
    State := 0;
ELSIF StartBatch AND Level >= LIQ_MIN AND EStop THEN
    CASE State OF
        0:
            IF Level < LVL_HIGH THEN
                State := 1;
            END_IF;
        1:
            IF Level >= LVL_HIGH THEN
                State := 2;
            END_IF;
        2:
            IF Temp >= TEMP_SET THEN
                State := 3;
            END_IF;
        3:
            IF TimeElapsed(ReactTimer) >= PT_REACT#T#3s THEN
                State := 4;
            END_IF;
        4:
            IF Level <= LVL_LOW THEN
                State := 0;
            END_IF;
    END_CASE;
END_IF;

CASE State OF
    0:
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    1:
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    2:
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
    3:
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
    4:
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;
END_CASE;

