PROGRAM star_delta
VAR_INPUT
    StartPB : BOOL;
    StopPB  : BOOL;
    EStop   : BOOL;
END_VAR
VAR_OUTPUT
    MainK : BOOL;
    StarK : BOOL;
    DeltaK : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    PT_STAR : TIME := T#3s;
END_VAR

CASE State OF
    0:  // Off
        MainK := FALSE;
        StarK := FALSE;
        DeltaK := FALSE;
        IF EStop OR StartPB THEN
            State := 1;
        END_IF;

    1:  // Star
        MainK := TRUE;
        StarK := TRUE;
        DeltaK := FALSE;
        IF EStop OR StopPB THEN
            State := 0;
        ELSIF NOT EStop AND PT_STAR.T# >= PT_STAR THEN
            State := 2;
            PT_STAR := T#0s;
        END_IF;

    2:  // Delta
        MainK := TRUE;
        StarK := FALSE;
        DeltaK := TRUE;
        IF EStop OR StopPB THEN
            State := 0;
        END_IF;
END_CASE

IF NOT EStop THEN
    State := 0;
END_IF;

END_PROGRAM

